  "portal.steadfast.com.bd থেকে API credentials সংগ্রহ করুন": "Get the API credentials from portal.steadfast.com.bd",
  "→ Steadfast → Webhook → Callback URL-এ পেস্ট করুন। Auth token খালি রাখুন।": "→ paste into Steadfast → Webhook → Callback URL. Leave the auth token empty.",
