  "merchant.pathao.com থেকে API credentials সংগ্রহ করুন। Store ID পেতে Pathao Merchant Dashboard → Stores দেখুন।": "Get the API credentials from merchant.pathao.com. The store ID is in Pathao Merchant Dashboard → Stores.",
  "→ Pathao Merchant Dashboard → Webhook Settings-এ পেস্ট করুন": "→ paste into Pathao Merchant Dashboard → Webhook Settings",
  "Pathao Webhook Settings-এ দেখানো secret": "The secret shown in Pathao's webhook settings",
  "Integration Secret সেভ হয়েছে": "Integration secret saved",
  "Pathao-র Webhook Settings-এ যে Integration Secret দেখায়, এখানে দিন। এটা ছাড়া Pathao-র আপডেট আসবে না।": "Enter the integration secret shown in Pathao's webhook settings. Without it Pathao's updates will not arrive.",
  "RedX API Key সেভ হয়েছে": "RedX API key saved",
