  "এগুলো নগদের টেস্ট (Sandbox) তথ্য — Live করতে নগদের Live Merchant ID ও চাবি দিন এবং API Base URL খালি করুন": "These are Nagad's test (sandbox) details — for live, enter Nagad's live merchant ID and keys and clear the API base URL",
  "Nagad PG Public Key সঠিক নয় — পুরো key টি (MII… দিয়ে শুরু) পেস্ট করুন": "The Nagad PG public key is not right — paste the whole key (starting MII…)",
  "Nagad ক্রেডেনশিয়াল আপডেট": "Nagad credentials updated",
  "Nagad সেটিংস সেভ হয়েছে": "Nagad settings saved",
  "চেকআউটে কোন পেমেন্ট দেখাবে, এখান থেকে ঠিক করুন। ক্যাশ অন ডেলিভারি সবসময় চালু থাকে।": "Choose which payments show at checkout. Cash on delivery is always on.",
  "এক অ্যাকাউন্টে bKash, Nagad, Rocket আর কার্ড। UddoktaPay প্যানেল → Brand Settings থেকে API Key আর আপনার পেমেন্ট ঠিকানা (Base URL) কপি করুন।": "bKash, Nagad, Rocket and cards in one account. Copy the API key and your payment address (base URL) from UddoktaPay panel → Brand Settings.",
  "bKash Merchant Portal থেকে Tokenized Checkout ক্রেডেনশিয়াল সংগ্রহ করুন। Sandbox মোডে টেস্ট করে তারপর Live-এ যান।": "Get the Tokenized Checkout credentials from the bKash merchant portal. Test in sandbox, then go live.",
  "টেস্ট মোড": "Test mode",
  "যেমন 683002007104225": "e.g. 683002007104225",
  "Sandbox (টেস্ট)": "Sandbox (test)",
  "(ঐচ্ছিক)": "(optional)",
  "ডিফল্ট: http://sandbox.mynagad.com:30001": "Default: http://sandbox.mynagad.com:30001",
  "ডিফল্ট: https://api.mynagad.com": "Default: https://api.mynagad.com",
  "Sandbox মোডে নগদ শুধু অ্যাডমিন হিসেবে লগইন থাকলে চেকআউটে দেখা যাবে — কাস্টমাররা দেখবে না, কারণ টেস্ট পেমেন্টে আসল টাকা কাটে না। Nagad থেকে Live ক্রেডেনশিয়াল পেলে সেগুলো বসিয়ে Environment \"Live\" করুন।": "In sandbox mode Nagad shows at checkout only to logged-in admins — customers don't see it, since test payments take no real money. With live credentials from Nagad, enter them and set the environment to \"Live\".",
  "Live মোডে চালু থাকলে সব কাস্টমার চেকআউটে নগদ দেখবে। API Base URL ফাঁকা রাখলে নগদের ডিফল্ট Live URL ব্যবহার হবে — Nagad অন্য URL দিলে সেটি বসান।": "In live mode every customer sees Nagad at checkout. Leave the API base URL empty to use Nagad's default live URL — enter another only if Nagad gives you one.",
  "📩 পেমেন্ট কনফার্মেশন SMS": "📩 Payment confirmation SMS",
  "পেমেন্ট SMS": "Payment SMS",
  "চালু থাকলে, সফল অনলাইন পেমেন্টের পর কাস্টমারকে একটি নিশ্চিতকরণ SMS পাঠানো হবে। ডিফল্টভাবে বন্ধ থাকে — খরচ নিয়ন্ত্রণে রাখতে প্রয়োজন অনুযায়ী চালু করুন। পেমেন্ট কনফার্মেশন ইমেইল সবসময় পাঠানো হবে (এই সুইচ শুধু SMS নিয়ন্ত্রণ করে)।": "When on, the customer gets a confirmation SMS after a successful online payment. Off by default to keep costs down. The payment confirmation email is always sent (this switch only controls the SMS).",
