  "স্টক ছাড়াই বিক্রি হবে, কখনো \"স্টক শেষ\" দেখাবে না। কয়টা বিক্রি হলো, পণ্যের তালিকায় দেখবেন।": "Sells without a stock count and never shows \"out of stock\". See how many sold in the product list.",
