  "একই ডিজাইনের অন্য রঙের প্রোডাক্ট আলাদাভাবে আপলোড করা থাকলে এখানে লিংক করুন — কাস্টমার যেকোনো একটায় গেলে বাকি রঙগুলো \"কালার অপশন\" হিসেবে দেখতে পাবে ও ক্লিক করে সেই প্রোডাক্টে চলে যেতে পারবে।": "If the same design in other colours is uploaded as separate products, link them here — on any one, customers see the other colours as \"colour options\" and can jump to them.",
